mapper.sql:
WHERE 1=1

  AND (UPPER(NVL(T1.CHECKLIST_ID,'')) LIKE '%'||UPPER(#{keyword})||'%'
    OR UPPER(NVL(T1.ITEM_NAME,'')) LIKE '%'||UPPER(#{keyword})||'%'
    OR UPPER(NVL(T1.CATEGORY_KO,'')) LIKE '%'||UPPER(#{keyword})||'%')

AND T1.CATEGORY_KO = #{categoryKo}
AND T1.ACTIVE_YN = #{activeYn}
AND T1.CHECKLIST_ID = #{checklistId}

mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT T1.CHECKLIST_ID AS CHECKLIST_ID, T1.ITEM_NAME AS ITEM_NAME, T1.CATEGORY_KO AS CATEGORY_KO,
           T1.SEVERITY_CD AS SEVERITY_CD, T1.ACTIVE_YN AS ACTIVE_YN, T1.SORT_NO AS SORT_NO, T1.REMARK AS REMARK
      FROM TB_IF_CHECKLIST_ITEM_PILOT T1

     ORDER BY T1.SORT_NO, T1.CHECKLIST_ID
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}

SELECT CHECKLIST_ID AS CHECKLIST_ID, ITEM_NAME AS ITEM_NAME, CATEGORY_KO AS CATEGORY_KO,
       SEVERITY_CD AS SEVERITY_CD, ACTIVE_YN AS ACTIVE_YN, SORT_NO AS SORT_NO, REMARK AS REMARK
  FROM TB_IF_CHECKLIST_ITEM_PILOT WHERE CHECKLIST_ID = #{checklistId}

mapper.insert:
INSERT INTO TB_IF_CHECKLIST_ITEM_PILOT (
  CHECKLIST_ID, ITEM_NAME, CATEGORY_KO, SEVERITY_CD, ACTIVE_YN, SORT_NO, REMARK
) VALUES (
  #{checklistId}, #{itemName}, #{categoryKo}, #{severityCd}, #{activeYn}, #{sortNo}, #{remark}
)

mapper.update:
UPDATE TB_IF_CHECKLIST_ITEM_PILOT SET
  ITEM_NAME=#{itemName}, CATEGORY_KO=#{categoryKo}, SEVERITY_CD=#{severityCd},
  ACTIVE_YN=#{activeYn}, SORT_NO=#{sortNo}, REMARK=#{remark}
 WHERE CHECKLIST_ID=#{checklistId}
